package com.strands.shell.wasm;

import static java.nio.charset.StandardCharsets.UTF_8;

import java.nio.file.Path;
import run.endive.runtime.ImportValues;
import run.endive.runtime.Instance;
import run.endive.runtime.Memory;
import run.endive.wasi.WasiOptions;
import run.endive.wasi.WasiPreview1;

/**
 * One reactor instance of the shell module; hostDir, when set, is preopened at /host. Calls go
 * through the typed {@link StrandsShell_ModuleExports} wrapper generated by the Endive plugin.
 */
final class ShellWasm implements AutoCloseable {

    record Result(int status, String stdout, String stderr) {}

    private final WasiPreview1 wasi;
    private final StrandsShell_ModuleExports exports;
    private final Memory memory;

    ShellWasm(Path hostDir) {
        var options = WasiOptions.builder().inheritSystemStreams();
        if (hostDir != null) {
            options = options.withDirectory("/host", hostDir);
        }
        wasi = WasiPreview1.builder().withOptions(options.build()).build();
        var instance =
                Instance.builder(StrandsShellModule.load())
                        .withImportValues(
                                ImportValues.builder()
                                        .addFunction(wasi.toHostFunctions())
                                        .build())
                        .withStart(false)
                        .withMachineFactory(StrandsShellModule::create)
                        .build();
        exports = new StrandsShell_ModuleExports(instance);
        exports._initialize();
        memory = exports.memory();
    }

    /** Copies a string into a guest buffer; the caller frees it with shellBufFree. */
    private int[] write(String s) {
        byte[] bytes = s.getBytes(UTF_8);
        int ptr = exports.shellBufAlloc(bytes.length);
        memory.write(ptr, bytes);
        return new int[] {ptr, bytes.length};
    }

    private String read(long packed) {
        return new String(memory.readBytes((int) (packed >>> 32), (int) packed), UTF_8);
    }

    String lastError() {
        return read(exports.shellLastError());
    }

    /** Returns the handle, or 0 with the reason in {@link #lastError()}. */
    int newShell(String toml) {
        int[] arg = write(toml);
        try {
            return exports.shellNew(arg[0], arg[1]);
        } finally {
            exports.shellBufFree(arg[0], arg[1]);
        }
    }

    int mustNewShell(String toml) {
        int handle = newShell(toml);
        if (handle == 0) {
            throw new IllegalStateException("shell_new: " + lastError());
        }
        return handle;
    }

    /** Returns the packed result pointer, or 0 for an invalid handle. */
    long rawRun(int handle, String script) {
        int[] arg = write(script);
        try {
            return exports.shellRun(handle, arg[0], arg[1]);
        } finally {
            exports.shellBufFree(arg[0], arg[1]);
        }
    }

    Result run(int handle, String script) {
        long packed = rawRun(handle, script);
        if (packed == 0) {
            throw new IllegalStateException("shell_run: " + lastError());
        }
        int ptr = (int) (packed >>> 32);
        int len = (int) packed;
        int status = memory.readInt(ptr);
        int outLen = memory.readInt(ptr + 4);
        int errLen = memory.readInt(ptr + 8);
        String stdout = new String(memory.readBytes(ptr + 12, outLen), UTF_8);
        String stderr = new String(memory.readBytes(ptr + 12 + outLen, errLen), UTF_8);
        exports.shellBufFree(ptr, len);
        return new Result(status, stdout, stderr);
    }

    void free(int handle) {
        exports.shellFree(handle);
    }

    @Override
    public void close() {
        wasi.close();
    }
}
